{
  "data": [
    {
      "query": "sales revenue",
      "target": "metric",
      "results": [
        {
          "score": 1.0,
          "properties": {
            "category": "Income_Statement",
            "description": "Net Sales or Revenue measures the company’s top-line performance from core operations after reductions such as discounts, returns, and certain pass-through taxes. For most commercial companies, this is the standard sales, revenue, turnover, income, or top-line figure used to assess business scale, growth, pricing, and demand. For banks, insurers, and other financial companies, this metric serves as the closest equivalent to sales or revenue and represents total operating revenue, including items such as interest income, fees, premiums earned, trading income, commissions, and other operating income. Analysts searching for sales or revenue across industries should use this metric as the primary top-line measure, while recognizing that in financial sectors it reflects industry-specific operating income rather than product sales in the traditional sense.",
            "metric": "FF_SALES",
            "name": "Net Sales or Revenue",
            "subcategory": "nan",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.70465237,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "International Sales measures revenue generated by a company’s operations in foreign countries, helping analysts understand the geographic mix of the top line outside the domestic market. Within the Income Statement, this metric is used to assess exposure to international demand, diversification across regions, and the contribution of overseas operations to overall sales growth. It generally excludes export sales as well as taxes such as excise, VAT, and GST, and may also exclude eliminations or certain corporate revenue items depending on company reporting. Analysts often use this metric when evaluating multinational expansion, foreign-market performance, and the sensitivity of revenue to global economic or currency trends.",
            "metric": "FF_SALES_INTL",
            "name": "International Sales",
            "subcategory": "INCOME_STATEMENT",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.5744976,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "Sales Per Share measures net sales or revenue generated for each share, providing a top-line per-share view of business scale. In the income statement per-share subcategory, it helps analysts compare revenue productivity across companies with different share counts and capital structures. This metric is typically calculated as sales divided by the share count used for diluted EPS when available, with basic or other common share measures used as fallbacks. It is especially relevant when evaluating revenue growth alongside EPS and other per-share fundamentals.",
            "metric": "FF_SALES_PS",
            "name": "Sales Per Share",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "True"
          }
        },
        {
          "score": 0.5035976,
          "properties": {
            "category": "RATIOS",
            "description": "This metric captures the year-over-year percentage change in net sales or revenue, showing how quickly a company’s top line is growing or declining. Within Ratios > Growth Rate, it is one of the core measures analysts use to evaluate commercial momentum, demand trends, and business expansion across reporting periods. It is especially relevant for comparing operating performance across companies, validating management guidance, and linking revenue growth to margins, earnings, and cash flow. If sales move from negative to positive, the growth calculation may be reported as not available.",
            "metric": "FF_SALES_GR",
            "name": "Sales - Net - 1 Year Growth",
            "subcategory": "GROWTH_RATE",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "EBIT operating income",
      "target": "metric",
      "results": [
        {
          "score": 1.0,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "EBIT (Operating Income) measures profit generated from core operations before interest and taxes, making it a key income statement metric for evaluating underlying operating performance. In this income statement context, it is typically calculated as net sales or revenue minus cost of goods sold, selling, general and administrative expenses, and other operating expenses; when those components are unavailable, reported operating income may be used as a substitute. Analysts use EBIT to compare operating profitability across periods, assess margin trends, and separate the effects of financing structure and tax jurisdiction from the performance of the business itself. This version is primarily applicable to commercial companies and certain other financial companies, where it serves as a standardized view of operating earnings in local currency.",
            "metric": "FF_EBIT_OPER",
            "name": "EBIT (Operating Income)",
            "subcategory": "INCOME_STATEMENT",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.6231131,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "Operating Income measures profit generated from the company’s core business activities before interest, investment-related returns, and income taxes. It is a key income statement metric for evaluating the earning power of the underlying business model, operating efficiency, and margin performance, independent of capital structure and tax effects. Analysts commonly use it to compare profitability across companies and periods, especially when assessing the strength and consistency of day-to-day operations.",
            "metric": "FF_OPER_INC",
            "name": "Operating Income",
            "subcategory": "INCOME_STATEMENT",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.6191018,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "This income statement metric measures EBITDA by adding operating income (EBIT) to depreciation, depletion, and amortization expense for the period. It is commonly used to evaluate core operating performance before the effects of non-cash charges and can help analysts compare profitability across companies with different capital intensity or depreciation policies. Within income statement analysis, this version is specifically calculated for commercial and other financial companies and serves as a practical proxy for operating cash-generating performance before financing, taxes, and non-cash amortization effects.",
            "metric": "FF_EBITDA_OPER",
            "name": "EBITDA (Operating Income Plus Depreciation & Amortization)",
            "subcategory": "INCOME_STATEMENT",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.55448353,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "Operating Income Per Share measures EBIT, or operating profit, on a per-share basis using the share count applied to diluted EPS and, when unavailable, the basic EPS share count. Within the Income Statement / Per Share subcategory, it shows how much core operating earnings the company generated for each common share before interest and taxes. Analysts use this metric to compare operating performance across companies with different capital structures or share counts and to assess whether improvements in profitability are translating into stronger per-share operating results.",
            "metric": "FF_EBIT_OPER_PS",
            "name": "Operating Income Per Share ",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "net income",
      "target": "metric",
      "results": [
        {
          "score": 1.0,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "Net Income is the bottom-line profit earned during the period after accounting for operating results, non-operating items, and discontinued operations. In this definition, it is calculated as net income before extraordinary items and preferred dividends minus discontinued operations, and is reported in local currency by default. Analysts use this core income statement metric to assess overall profitability, earnings trends, and the amount of profit available to common shareholders after major period-specific impacts.",
            "metric": "FF_NET_INC",
            "name": "Net Income",
            "subcategory": "INCOME_STATEMENT",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.7132595,
          "properties": {
            "category": "Income_Statement",
            "description": "Net Income Attributable to Parent represents the portion of total net income that belongs to the parent company’s common shareholders after deducting income attributable to non-controlling interests. In the Income Statement category’s Net Income subcategory, this is a key bottom-line profitability measure for evaluating the earnings actually available to the parent entity. Analysts use it when assessing shareholder returns, earnings trends, and valuation metrics for companies with partially owned subsidiaries, particularly in bank and insurance reporting structures.",
            "metric": "FF_NET_INC_PARENT",
            "name": "Net Income Attributable to Parent",
            "subcategory": "Net_Income",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.70358324,
          "properties": {
            "category": "Income_Statement",
            "description": "This income statement metric captures the net income amount used as the numerator in earnings per share (EPS) calculations. It is typically net income available to common shareholders after preferred dividends, and may reflect common-equivalent or fully diluted assumptions depending on the company’s reporting. Analysts use it to understand exactly which profit figure underlies reported EPS and to compare basic versus diluted earnings attribution across periods or companies.",
            "metric": "FF_NET_INC_CALC_EPS",
            "name": "Net Income Used to Calculate EPS",
            "subcategory": "nan",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.6969426,
          "properties": {
            "category": "Income_Statement",
            "description": "Net Investment Income is an income statement revenue metric that measures income earned from investment assets after related investment expenses, particularly for insurance and other financial companies. It can include interest income, dividends, rental income, capital gains, option premiums, royalty or annuity income, and certain investment banking or securities-related gains, depending on the reporting entity. Within the Revenues subcategory, this metric helps analysts evaluate how much of a company’s top-line earnings are generated from invested assets rather than underwriting, lending, or other core operations. It is especially relevant when analyzing insurers, where investment performance is a key driver of profitability.",
            "metric": "FF_INS_INVEST_INC",
            "name": "NET INVESTMENT INCOME",
            "subcategory": "Revenues",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "diluted EPS",
      "target": "metric",
      "results": [
        {
          "score": 0.9711264,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "EPS - Fully-Diluted measures net income available to common shareholders divided by the fully diluted share count, reflecting the earnings attributable to each share after considering potential dilution from securities such as options or convertible instruments. In the Income Statement / Per Share subcategory, this is one of the most widely used per-share profitability metrics because it presents a more conservative view than basic EPS. Analysts rely on diluted EPS to evaluate shareholder earnings power, compare reported results with consensus estimates, and assess valuation metrics such as the price-to-earnings ratio on a fully diluted basis.",
            "metric": "FF_EPS_DIL",
            "name": "EPS - Fully-Diluted",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "True"
          }
        },
        {
          "score": 0.8945488,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "This metric shows diluted earnings per share after extraordinary items, reflecting the profit available to common shareholders spread across the diluted share count. Because it uses diluted shares, it incorporates the potential impact of securities such as options, warrants, or convertible instruments that could increase shares outstanding. Analysts use this per-share income statement measure to assess a more conservative view of shareholder profitability and to compare reported earnings power after unusual items on a dilution-adjusted basis. It is particularly useful when evaluating companies with meaningful potential share dilution.",
            "metric": "FF_EPS_DIL_AFT_XORD",
            "name": "EPS - Diluted - After Extraordinary Items",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.79358315,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "This per-share income statement metric measures diluted earnings per share before unusual expense items, showing what the company earned for each share after assuming the impact of potentially dilutive securities. It is calculated as net income before unusual expense divided by the fully diluted share count used for EPS, with basic shares used as a fallback if diluted shares are not available. Analysts use it to evaluate underlying per-share profitability while excluding unusual charges that may distort period results, making it useful for normalized earnings analysis and company comparisons.",
            "metric": "FF_EPS_DIL_BEF_UNUSUAL",
            "name": "EPS - Diluted - Before Unusual Expense",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "True"
          }
        },
        {
          "score": 0.7816591,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "This income statement metric measures the net income available to common shareholders that is used as the numerator in fully diluted earnings per share (EPS). It reflects profit after amounts attributable to preferred shareholders or other non-common claims have been removed, providing the earnings base relevant to common equity holders on a diluted basis. Analysts use this figure when evaluating per-share profitability, comparing reported diluted EPS calculations, and assessing how potential dilution from options, convertibles, or other securities affects earnings attributable to common stock.",
            "metric": "FF_NET_INC_DIL",
            "name": "Net Income Available to Common Fully Diluted EPS",
            "subcategory": "INCOME_STATEMENT",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "diluted shares outstanding",
      "target": "metric",
      "results": [
        {
          "score": 0.9699066,
          "properties": {
            "category": "MARKET_DATA",
            "description": "This metric represents the number of shares a company uses to calculate fully diluted earnings per share, reflecting the share count after considering the impact of potentially dilutive securities when reported by the company. In market data and per-share analysis, it is essential for understanding how options, convertible instruments, and other dilution sources can affect reported EPS and shareholder economics. Analysts use this measure when comparing basic versus diluted profitability, modeling per-share performance, and assessing the true earnings attributable to each share on a fully diluted basis.",
            "metric": "FF_COM_SHS_OUT_EPS_DIL",
            "name": "Common Shares Used To Calculate Fully Diluted Earnings Per Share",
            "subcategory": "MARKET_DATA",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.90496206,
          "properties": {
            "category": "MARKET_DATA",
            "description": "Common Shares Outstanding measures the total number of common or ordinary shares issued and still outstanding at the end of the reporting period, net of treasury stock. Within Market Data, this is a core share-count metric used to assess a company’s equity base and to support valuation and ownership analysis, including market capitalization, earnings per share, and dilution trends. It can incorporate multiple share classes that are normalized to a primary share basis, making it especially useful when comparing companies with complex capital structures. Analysts typically use this metric when evaluating per-share performance, changes in capital structure, stock issuance or buyback activity, and shareholder dilution over time.",
            "metric": "FF_COM_SHS_OUT",
            "name": "Common Shares Outstanding",
            "subcategory": "MARKET_DATA",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.8347214,
          "properties": {
            "category": "MARKET_DATA",
            "description": "Represents the number of common or ordinary shares outstanding for a specific security at period end, calculated as issued shares less treasury shares. Within Market Data, this is a core share-count metric used in market capitalization, per-share analysis, dilution review, and ownership calculations. For companies with multiple share classes, it captures the security-level share count for the relevant share type, and the data is typically split-adjusted to support consistent historical analysis.",
            "metric": "FF_COM_SHS_OUT_SECS",
            "name": "Common Shares Outstanding - Security",
            "subcategory": "MARKET_DATA",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.76744795,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "This metric shows diluted earnings per share after extraordinary items, reflecting the profit available to common shareholders spread across the diluted share count. Because it uses diluted shares, it incorporates the potential impact of securities such as options, warrants, or convertible instruments that could increase shares outstanding. Analysts use this per-share income statement measure to assess a more conservative view of shareholder profitability and to compare reported earnings power after unusual items on a dilution-adjusted basis. It is particularly useful when evaluating companies with meaningful potential share dilution.",
            "metric": "FF_EPS_DIL_AFT_XORD",
            "name": "EPS - Diluted - After Extraordinary Items",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "return on invested capital",
      "target": "metric",
      "results": [
        {
          "score": 1.0,
          "properties": {
            "category": "RATIOS",
            "description": "Return on Average Invested Capital is a profitability ratio that measures how efficiently a company generates net income from the capital invested in the business over the period. It is calculated as net income divided by the two-period average of total invested capital, with last-twelve-month net income used for quarterly or semiannual analysis. Analysts use this metric to evaluate management’s effectiveness in deploying debt and equity capital and to compare capital efficiency across companies, business units, or time periods within the Ratios/Profitability framework.",
            "metric": "FF_ROIC",
            "name": "Return on Average Invested Capital",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.84004545,
          "properties": {
            "category": "RATIOS",
            "description": "Cash Flow Return on Average Invested Capital is a profitability ratio that measures how efficiently a company converts the capital invested in the business into operating cash flow. It is calculated as net cash from operating activities divided by average total invested capital, expressed as a percentage; for quarterly or semiannual analysis, the numerator typically uses last-twelve-month operating cash flow. Analysts use this metric to evaluate capital efficiency from a cash-generation perspective, especially when comparing companies with different non-cash expenses, accounting policies, or capital intensity. Within Ratios/Profitability, it is particularly useful for assessing whether management is producing strong cash returns on the funds committed to the business.",
            "metric": "FF_CF_ROIC",
            "name": "Cash Flow Return on Average Invested Capital",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "True"
          }
        },
        {
          "score": 0.5892458,
          "properties": {
            "category": "RATIOS",
            "description": "Return on Average Total Capital measures how effectively a company earns operating income from the capital invested in the business, using an average capital base across two fiscal periods. It is calculated as Operating Income divided by average Total Capital including short-term debt plus average accumulated minority interest, multiplied by 100. As a Ratios > Profitability metric, it is commonly used to evaluate operating performance independent of financing structure and to compare how efficiently companies deploy debt and equity capital to generate returns. Analysts often use this measure in trend analysis, peer comparisons, and capital allocation reviews; for quarterly or semiannual requests, the calculation uses last-twelve-month operating income.",
            "metric": "FF_ROTC",
            "name": "Return on Average Total Capital",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.5733507,
          "properties": {
            "category": "RATIOS",
            "description": "Return on Common Equity measures the return generated for common shareholders by comparing income available to common equity with the average common equity base, expressed as a percentage. As a profitability ratio, it indicates how effectively management is using common shareholders’ capital to produce earnings. Analysts use it to assess shareholder value creation, compare capital efficiency across companies, and track whether returns are improving or deteriorating over time; for interim analysis, the income component is typically evaluated on a last-twelve-month basis.",
            "metric": "FF_ROCE",
            "name": "Return on Common Equity",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "return on equity",
      "target": "metric",
      "results": [
        {
          "score": 1.0,
          "properties": {
            "category": "RATIOS",
            "description": "Return on Common Equity measures the return generated for common shareholders by comparing income available to common equity with the average common equity base, expressed as a percentage. As a profitability ratio, it indicates how effectively management is using common shareholders’ capital to produce earnings. Analysts use it to assess shareholder value creation, compare capital efficiency across companies, and track whether returns are improving or deteriorating over time; for interim analysis, the income component is typically evaluated on a last-twelve-month basis.",
            "metric": "FF_ROCE",
            "name": "Return on Common Equity",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.9090623,
          "properties": {
            "category": "RATIOS",
            "description": "Return on Average Total Equity (ROE) measures how effectively a company generates net income from the shareholders’ capital invested in the business. It is calculated as net income divided by average total shareholders’ equity, expressed as a percentage; for quarterly or semiannual periods, the calculation typically uses last-twelve-month net income and an average equity base spanning the current and year-ago period. Analysts use ROE as a core profitability ratio to evaluate management performance, capital allocation, and the company’s ability to create value for equity holders. Within Ratios/Profitability, it is one of the most widely used measures for comparing earnings power across companies and over time.",
            "metric": "FF_ROE",
            "name": "Return on Average Total Equity",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.73371994,
          "properties": {
            "category": "RATIOS",
            "description": "This profitability ratio shows how effectively a company generates cash-based earnings relative to the capital provided by common shareholders. It is calculated as funds from operations divided by average total common equity, expressed as a percentage, and provides a cash-oriented view of return on equity rather than an accounting-only measure. Analysts use it to evaluate the quality and sustainability of shareholder returns, especially when comparing companies with different non-cash charges, working capital profiles, or earnings adjustments. It is particularly relevant in assessing whether common equity is producing strong operating cash returns over time.",
            "metric": "FF_CASH_ROCE",
            "name": "Cash Earnings Return on Common Equity",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.7336049,
          "properties": {
            "category": "RATIOS",
            "description": "Return on Earning Assets measures how effectively a financial institution generates net income from its earning asset base, primarily average total investments and average net loans. It is calculated as Net Income After Extraordinary Items divided by the sum of the two-period average of Total Investments and the two-period average of Net Loans, multiplied by 100; for quarterly or semiannual reporting, the numerator uses last-twelve-month net income. Analysts use this banking-oriented profitability metric to assess asset productivity, compare earnings power across lenders, and evaluate how efficiently balance-sheet assets are being deployed.",
            "metric": "FF_ROEA",
            "name": "Return on Earning Assets",
            "subcategory": "PROFITABILITY",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "free cash flow",
      "target": "metric",
      "results": [
        {
          "score": 0.9915974,
          "properties": {
            "category": "FINANCIAL_SERVICES",
            "description": "Free Cash Flow is a supplemental cash flow metric that measures the cash a business generates after funding its core operations and required investment in fixed assets. It is typically calculated as net cash from operating activities minus capital expenditures for fixed assets, helping analysts assess how much cash remains available for debt repayment, acquisitions, share repurchases, dividends, or reinvestment. Within the cash flow category, this metric is widely used to evaluate financial flexibility, capital discipline, and the sustainability of shareholder returns. FactSet’s standard Free Cash Flow methodology does not subtract dividends, though an alternative methodology may deduct cash dividends paid for analysts who want a more conservative view of residual cash generation.",
            "metric": "FF_FREE_CF",
            "name": "Free Cash Flow",
            "subcategory": "SUPPLEMENTAL",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "1000000"
          }
        },
        {
          "score": 0.6917519,
          "properties": {
            "category": "BALANCE_SHEET",
            "description": "Cash Flow Per Share (Diluted) - Free measures free cash flow attributable to each diluted share for the period. Within the cash flow per-share subcategory, it is calculated as free cash flow divided by diluted shares used for EPS, with basic shares used when diluted shares are unavailable; depending on methodology, free cash flow may be presented before or after dividends. Analysts use this metric to assess how much cash remains per share after funding the business, supporting valuation work, dividend capacity analysis, and comparisons of shareholder cash generation across companies.",
            "metric": "FF_FREE_PS_CF",
            "name": "Cash Flow Per Share (Diluted) - Free",
            "subcategory": "PER_SHARE",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "True"
          }
        },
        {
          "score": 0.57353294,
          "properties": {
            "category": "RATIOS",
            "description": "Free Cash Flow Yield is a valuation ratio that shows how much free cash flow a company generates relative to its share price, expressed as a percentage. In this definition, the numerator uses free cash flow after dividends on a per-share basis, making it especially useful for assessing the cash return available to equity investors compared with the market price they pay. Analysts use this metric within valuation analysis to compare cash-generating strength across companies, identify potentially undervalued stocks, and evaluate whether a company’s market valuation is supported by recurring cash production. For interim analysis, quarterly or semiannual requests typically use a last-twelve-months free cash flow basis to improve comparability.",
            "metric": "FF_FCF_YLD",
            "name": "Free Cash Flow Yield",
            "subcategory": "VALUATION",
            "type": "metric",
            "dataProduct": "fundamentals"
          }
        },
        {
          "score": 0.5148646,
          "properties": {
            "category": "RATIOS",
            "description": "Price to Free Cash Flow measures how much investors are paying for each unit of free cash flow generated on a per-share basis. As a valuation ratio, it helps analysts judge whether a company’s stock price is supported by cash generation rather than accounting earnings, making it useful for comparing businesses with different capital intensity or non-cash expense profiles. This metric is commonly used in equity valuation, cash-flow-based screening, and identifying companies that may appear expensive on earnings but attractive on free cash flow.",
            "metric": "FF_PFCF",
            "name": "Price to Free Cash Flow",
            "subcategory": "VALUATION",
            "type": "metric",
            "dataProduct": "fundamentals",
            "factor": "True"
          }
        }
      ],
      "searchParameters": {
        "limit": 4
      }
    },
    {
      "query": "net debt to EBITDA",
      "target": "metric",
      "results": [
        {
          "score": 1.0,
